insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-breaks-activity', 'Breaks and activity', 'Start and end your breaks next to the clock. While you are clocked in, the portal notes only that you are active.', array['va/your-workday']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 1, 'Your breaks', '[{"caption":"No fixed length","say":"Take a break when you need one. Press Start break next to the clock, and End break when you are back.","visual":{"kind":"title","heading":"Breaks","text":"At your discretion"}},{"caption":"Every break is kept","say":"Each break keeps its start, its end and a reason if you give one. You see them on My hours.","visual":{"kind":"steps","heading":"A break","items":["Press Start break (a reason is optional)","The timer runs on your home page","Press End break when you are back"]}},{"caption":"A reminder","say":"A break still open after 30 minutes reminds you, and the Admins see it. Clocking out ends a break by itself.","visual":{"kind":"rule","heading":"Forgot to end it?","text":"You get a reminder after 30 minutes. Only an Admin can change a break afterwards, with a reason.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 2, 'Activity while clocked in', '[{"caption":"What is noted","say":"While you are clocked in and not on a break, the portal notes that you are active: a click, a key, a scroll or switching to its tab.","visual":{"kind":"list","heading":"Counted as active","items":["A click, a key or a scroll in the portal","Anything you do in the portal","A phone call you take or make","The townhall"]}},{"caption":"What is never noted","say":"It never records what you type, which pages you open, or your screen.","visual":{"kind":"rule","heading":"Only the fact","text":"No keystrokes, no pages, no screenshots.","tone":"ok"}},{"caption":"Keep the tab open","say":"Keep the portal open while you work. After a few minutes without activity it asks Still there? Tap anywhere to carry on. Nothing is counted outside your scheduled hours.","visual":{"kind":"rule","heading":"A hidden tab","text":"A tab nobody touches counts as inactive, and the Admins are told after 10 minutes.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 1, 'How long can a break be?', '["Exactly 15 minutes","There is no fixed length","One hour a day","Only at lunch time"]'::jsonb, 1, 'Breaks are at your discretion; each one is kept with its start and end.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 2, 'What does the portal record while you are clocked in?', '["What you type","The pages you open","Only the fact that you are active","Screenshots"]'::jsonb, 2, 'Only the fact of activity: never keys, pages or screens.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 3, 'You forgot to press End break. What happens?', '["Nothing","After 30 minutes you get a reminder and the Admins see it","Your day is deleted","You are clocked out at once"]'::jsonb, 1, 'A break open past 30 minutes reminds you; clocking out also ends it.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 4, 'Who can change a break after it has ended?', '["Anyone on the team","You, at any time","Only an Admin, with a reason","Nobody, ever"]'::jsonb, 2, 'Only an Admin can change a break afterwards, and the reason is kept.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-breaks-activity'), 5, 'Which of these counts as active?', '["A hidden tab nobody touches","A phone call you take","Being clocked out","Time after your scheduled hours"]'::jsonb, 1, 'Calls you take or make and the townhall count as active.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'cs', (select id from academy_sections where slug = 'new-r35-breaks-activity'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'cs' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-r35-breaks-activity'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'finance', (select id from academy_sections where slug = 'new-r35-breaks-activity'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'finance' on conflict (path_code, section_id) do nothing;
