-- 1828: the academy's customer service, Fleet and Finance paths get Breaks and activity (docs/changes/2026-11-11-r35d-breaks-idle.md,
-- 1800): Start and End break, the reminder, and what the activity tracker notes (the fact only). No applied migration is edited.
-- One section (supabase/seed/academy/r35d.mjs, generated below). Staff who had passed every section of their path keep a week
-- before the new section holds them (as 1040 did); nothing is reset.
create temp table r35d_done on commit drop as
select distinct e.user_id from academy_enrollments e where e.path_code in ('cs', 'fleet', 'finance') and app.academy_done(e.user_id);

-- ACADEMY 1828 START (generated by supabase/seed/1828_gen_academy.mjs from supabase/seed/academy/r35d.mjs; do not edit by hand)
-- ACADEMY 1828 END

update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days')
  from r35d_done d where e.user_id = d.user_id and e.gate;
